import{_ as i,o as t,c as s,a2 as a}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"Wie steuere ich Rollläden, Lüfter, Schlösser und Klimageräte?","description":"","frontmatter":{"order":4,"adapter":"esphome","editLink":"https://github.com/DrozmotiX/ioBroker.esphome/edit/main/docs/de/03.referenz/04.cover-luefter-schloss-klima.md"},"headers":[],"relativePath":"de/adapter/esphome/referenz/cover-luefter-schloss-klima.md","filePath":"de/adapter/esphome/referenz/cover-luefter-schloss-klima.md","lastUpdated":1795562976000}'),n={name:"de/adapter/esphome/referenz/cover-luefter-schloss-klima.md"};function o(d,e,r,l,h,c){return t(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="wie-steuere-ich-rollladen-lufter-schlosser-und-klimagerate" tabindex="-1">Wie steuere ich Rollläden, Lüfter, Schlösser und Klimageräte? <a class="header-anchor" href="#wie-steuere-ich-rollladen-lufter-schlosser-und-klimagerate" aria-label="Permalink to &quot;Wie steuere ich Rollläden, Lüfter, Schlösser und Klimageräte?&quot;">​</a></h1><p><a id="control-covers-including-time-based"></a></p><h2 id="wie-steuere-ich-rollladen-und-covers-auch-time-based-position-neigung-stopp" tabindex="-1">Wie steuere ich Rollläden und Covers (auch time_based): Position, Neigung, Stopp? <a class="header-anchor" href="#wie-steuere-ich-rollladen-und-covers-auch-time-based-position-neigung-stopp" aria-label="Permalink to &quot;Wie steuere ich Rollläden und Covers (auch time_based): Position, Neigung, Stopp?&quot;">​</a></h2><p>Ein Cover hat unter <code>esphome.0.&lt;Gerät&gt;.Cover.&lt;Schlüssel&gt;</code> die Datenpunkte <code>position</code>, <code>tilt</code> und <code>stop</code>. Position und Neigung liest und schreibst du in Prozent: <code>0</code> = zu, <code>100</code> = offen.</p><table tabindex="0"><thead><tr><th>Datenpunkt</th><th>Werte</th><th>Rolle</th></tr></thead><tbody><tr><td><code>position</code></td><td>0 bis 100 %</td><td><code>level.blind</code></td></tr><tr><td><code>tilt</code></td><td>0 bis 100 %</td><td><code>level.tilt</code></td></tr><tr><td><code>stop</code></td><td>jeder geschriebene Wert hält das Cover an</td><td><code>button</code></td></tr></tbody></table><p>Für Öffnen und Schließen gibt es keinen eigenen Datenpunkt, du schreibst <code>100</code> oder <code>0</code> in <code>position</code>. Kann dein Cover keine Neigung, ignorierst du <code>tilt</code>. VIS-Schieberegler und Sprachassistenten für die Rolle <code>level.blind</code> funktionieren ohne Umrechnung.</p><h3 id="so-fahrst-du-einen-rollladen-auf-eine-position" tabindex="-1">So fährst du einen Rollladen auf eine Position <a class="header-anchor" href="#so-fahrst-du-einen-rollladen-auf-eine-position" aria-label="Permalink to &quot;So fährst du einen Rollladen auf eine Position&quot;">​</a></h3><ol><li>Öffne im Admin den Tab „Objekte“ und dort <code>esphome.0.&lt;Gerät&gt;.Cover.&lt;Schlüssel&gt;</code>.</li><li>Schreib den Zielwert in <code>position</code>, z. B. <code>30</code> für 30 % offen.</li><li>Das Gerät fährt los und meldet seine Position zurück. Der Datenpunkt zeigt sie dann bestätigt (<code>ack = true</code>).</li><li>Zum Anhalten schreibst du <code>true</code> in <code>stop</code>.</li></ol><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;esphome.0.&lt;Gerät&gt;.Cover.&lt;Schlüssel&gt;.position&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;esphome.0.&lt;Gerät&gt;.Cover.&lt;Schlüssel&gt;.stop&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Bleibt <code>position</code> immer bei 0, meldet das Gerät keine Position über die API. Bei <code>time_based</code>-Covern hängt das von der YAML ab, der Adapter zeigt nur, was ankommt.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/automatisieren#use-esphome-datapoints-aliases-alexa">Datenpunkte in Aliasen verwenden</a> · <a href="./datenpunkte#command-acknowledged-ack-happens-offline">Wann ein Befehl als bestätigt gilt</a> · <a href="./datenpunkte#datapoint-path-contain-number-instead">Warum im Pfad eine Zahl steht</a></p><p><a id="control-esphome-fan-speed-direction"></a></p><h2 id="wie-steuere-ich-einen-esphome-lufter-geschwindigkeit-richtung-oszillation" tabindex="-1">Wie steuere ich einen ESPHome-Lüfter (Geschwindigkeit, Richtung, Oszillation)? <a class="header-anchor" href="#wie-steuere-ich-einen-esphome-lufter-geschwindigkeit-richtung-oszillation" aria-label="Permalink to &quot;Wie steuere ich einen ESPHome-Lüfter (Geschwindigkeit, Richtung, Oszillation)?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="operate-esphome-lock"></a></p><h2 id="wie-bediene-ich-ein-esphome-schloss-lock" tabindex="-1">Wie bediene ich ein ESPHome-Schloss (Lock)? <a class="header-anchor" href="#wie-bediene-ich-ein-esphome-schloss-lock" aria-label="Permalink to &quot;Wie bediene ich ein ESPHome-Schloss (Lock)?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p><p><a id="control-climate-device-example-midea"></a></p><h2 id="wie-steuere-ich-ein-klimagerat-z-b-midea-umbau" tabindex="-1">Wie steuere ich ein Klimagerät (z. B. Midea-Umbau)? <a class="header-anchor" href="#wie-steuere-ich-ein-klimagerat-z-b-midea-umbau" aria-label="Permalink to &quot;Wie steuere ich ein Klimagerät (z. B. Midea-Umbau)?&quot;">​</a></h2><p><em>Dieser Abschnitt wird noch geschrieben.</em></p>`,20)])])}const m=i(n,[["render",o]]);export{u as __pageData,m as default};
